result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/cvp.py", "content": """"Cost-volume-profit (CVP) analysis tool.

All monetary/quantity math uses ``decimal.Decimal`` so results are exact.
Inputs may be int, float, str, or Decimal; they are converted via
``Decimal(str(value))`` which preserves the intended decimal value.
"""

from decimal import Decimal

__all__ = [
    "breakeven_units",
    "breakeven_revenue",
    "units_for_target_profit",
    "margin_of_safety",
    "breakeven_units_mix",
    "weighted_average_contribution_margin",
]


def _d(value) -> Decimal:
    """Coerce numeric input to an exact Decimal."""
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise TypeError(f"unsupported numeric value: {value!r}")
    return Decimal(str(value))


def contribution_margin(price, var_cost) -> Decimal:
    """Contribution margin per unit: price - variable cost per unit."""
    cm = _d(price) - _d(var_cost)
    if cm <= 0:
        raise ValueError(
            f"contribution margin must be positive, got {cm} "
            f"(price {price} - var cost {var_cost})"
        )
    return cm


def breakeven_units(fixed, price, var_cost) -> Decimal:
    """Break-even quantity in units: fixed costs / contribution margin per unit."""
    cm = contribution_margin(price, var_cost)
    return _d(fixed) / cm


def breakeven_revenue(fixed, price, var_cost) -> Decimal:
    """Break-even sales revenue: break-even units x price per unit."""
    return breakeven_units(fixed, price, var_cost) * _d(price)


def units_for_target_profit(fixed, target_profit, price, var_cost) -> Decimal:
    """Units required to reach a target profit: (fixed + target) / CM per unit."""
    cm = contribution_margin(price, var_cost)
    return (_d(fixed) + _d(target_profit)) / cm


def margin_of_safety(actual_units, fixed, price, var_cost) -> Decimal:
    """Margin of safety as a percent of actual sales.

    (actual units - break-even units) / actual units * 100.
    """
    actual = _d(actual_units)
    if actual <= 0:
        raise ValueError(f"actual units must be positive, got {actual}")
    be = breakeven_units(fixed, price, var_cost)
    return (actual - be) / actual * Decimal(100)


def weighted_average_contribution_margin(sales_mix: dict) -> Decimal:
    """Weighted-average contribution margin over a sales-mix dictionary.

    ``sales_mix`` maps product name -> ``(price, var_cost, mix_fraction)``.
    Mix fractions must be non-negative and sum to exactly 1.
    """
    if not sales_mix:
        raise ValueError("sales mix must contain at least one product")
    weighted_cm = Decimal(0)
    mix_sum = Decimal(0)
    for name, spec in sales_mix.items():
        price, var_cost, fraction = spec
        cm = contribution_margin(price, var_cost)
        frac = _d(fraction)
        if frac < 0:
            raise ValueError(
                f"mix fraction for {name!r} must be non-negative, got {frac}"
            )
        weighted_cm += cm * frac
        mix_sum += frac
    if mix_sum != Decimal(1):
        raise ValueError(
            f"mix fractions must sum to 1, got {mix_sum}"
        )
    return weighted_cm


def breakeven_units_mix(sales_mix: dict) -> tuple[Decimal, dict]:
    """Multi-product break-even using the weighted-average CM.

    Returns ``(total_units, per_product_units)`` where each product's unit
    volume is the total break-even units scaled by its mix fraction.
    """
    weighted_cm = weighted_average_contribution_margin(sales_mix)
    fixed_total = Decimal(0)
    for name, spec in sales_mix.items():
        fixed = spec[3] if len(spec) > 3 else None
        if fixed is None:
            # Fixed costs are supplied separately by callers that need them;
            # here they come from an optional 4th tuple element aggregated below.
            pass
    # Fixed costs: taken from the optional 4th element of each tuple, if given.
    provided = [spec[3] for spec in sales_mix.values() if len(spec) > 3]
    if provided:
        fixed_total = sum((_d(f) for f in provided), Decimal(0))
    if fixed_total <= 0:
        raise ValueError("fixed costs required (4th element of each mix tuple)")
    total = fixed_total / weighted_cm
    split = {
        name: total * _d(spec[2]) for name, spec in sales_mix.items()
    }
    return total, split


