import pytest

from cvp import (
    breakeven_units,
    breakeven_revenue,
    units_for_target_profit,
    margin_of_safety,
    breakeven_units_mix,
    weighted_average_contribution_margin,
)
from decimal import Decimal

D = Decimal

MIX = {"A": (30, 18, D("0.6")), "B": (50, 26, D("0.4"))}


def test_breakeven_units_exact():
    assert breakeven_units(90_000, 25, 15) == D(9_000)


def test_breakeven_revenue_exact():
    assert breakeven_revenue(90_000, 25, 15) == D(225_000)


def test_nonpositive_contribution_margin_raises():
    with pytest.raises(ValueError):
        breakeven_units(10_000, 15, 15)   # zero CM
    with pytest.raises(ValueError):
        breakeven_units(10_000, 10, 15)   # negative CM


def test_units_for_target_profit_exact():
    assert units_for_target_profit(90_000, 30_000, 25, 15) == D(12_000)


def test_weighted_average_cm_exact():
    assert weighted_average_contribution_margin(MIX) == D("16.8")


def test_mix_breakeven_total_and_split():
    total, split = breakeven_units_mix(84_000, MIX)
    assert total == D(5_000)
    assert split["A"] == D(3_000)
    assert split["B"] == D(2_000)
    assert split["A"] + split["B"] == total


def test_mix_fractions_not_summing_to_one_raise():
    bad = {"A": (30, 18, D("0.6")), "B": (50, 26, D("0.3"))}
    with pytest.raises(ValueError):
        breakeven_units_mix(84_000, bad)


def test_margin_of_safety_exact_percent():
    assert margin_of_safety(12_000, 90_000, 25, 15) == D(25)
